// A name in another module is reached by naming that module, so that is the
// text offered: an import binds the module's name and nothing else, and a bare
// `size` here would be a name no import can make work.
import ledger

fn main() -> UInt8 {
    twice(ledger.size())
}

// The same module, a file that wrote no import. An import binds a module name
// inside the file that wrote it, so `ledger` is a name nothing has bound here,
// and it is offered the way any module nobody imported is: carrying the import
// that would bind it.
fn twice(n: UInt8) -> UInt8 {
    n + n
}
